import artefact from "./calibration-elo-xp.json";

// The calibration artefact (amendment A7, contract §15). calibration-elo-xp.json is generated by
// docs/audits/calibration-elo-xp/make_artifact.py: never edited by hand and never recalculated here.
// An edge is usable only if the artefact lists it as admitted; anything else is "calibration unavailable".
export type EloEdge = "upper95" | "upper99" | "lower95" | "lower99";
export interface Calibration {
  calibratedThrough: string;
  elo: { kMax: number; bounds: Partial<Record<EloEdge, Record<number, number>>> }; // admitted edges only, by k
  xp: Record<number, { upper95?: number; upper99?: number }>; // admitted quantiles of the rate ratio, by window days
}

const EDGES: EloEdge[] = ["upper95", "upper99", "lower95", "lower99"];

export function parseCalibration(a: unknown): Calibration {
  const x = a as any;
  if (typeof x?.calibratedThrough !== "string" || !x.elo?.edges || !x.elo.admitted || typeof x.elo.kMax !== "number" || !x.xp?.admitted)
    throw new Error("calibration-elo-xp.json: malformed");
  const bounds: Calibration["elo"]["bounds"] = {};
  for (const e of EDGES) {
    for (const k of x.elo.admitted[e] ?? []) {
      const b = x.elo.edges[e]?.[String(k)]?.bound;
      if (typeof b !== "number" || !Number.isFinite(b)) throw new Error(`calibration-elo-xp.json: admitted ${e} k=${k} has no bound`);
      (bounds[e] ??= {})[k] = b;
    }
  }
  const xp: Calibration["xp"] = {};
  for (const [w, q] of Object.entries<any>(x.xp.admitted)) xp[Number(w)] = { upper95: q.upper95, upper99: q.upper99 };
  return { calibratedThrough: x.calibratedThrough, elo: { kMax: x.elo.kMax, bounds }, xp };
}

export const CALIBRATION: Calibration = parseCalibration(artefact);

export type Calibrated = { available: false } | { available: true; relevant: boolean; level: "relevant" | "exceptional" | null; lower: number | null; upper: number | null };

// ELO: the band depends on k (games played), exactly on the validated grid and never beyond kMax; each direction needs its own admitted edge.
export function eloVerdict(delta: number, k: number, cal: Calibration = CALIBRATION): Calibrated {
  const dir = delta >= 0 ? "upper" : "lower";
  const b95 = cal.elo.bounds[`${dir}95` as EloEdge]?.[k];
  if (k > cal.elo.kMax || b95 === undefined) return { available: false };
  const b99 = cal.elo.bounds[`${dir}99` as EloEdge]?.[k];
  const out = dir === "upper" ? delta > b95 : delta < b95;
  const exceptional = b99 !== undefined && (dir === "upper" ? delta > b99 : delta < b99);
  return { available: true, relevant: out, level: exceptional ? "exceptional" : out ? "relevant" : null, lower: dir === "lower" ? b95 : null, upper: dir === "upper" ? b95 : null };
}

// XP: one-sided (acceleration only), by exact window length.
export function xpVerdict(ratio: number, windowDays: number, cal: Calibration = CALIBRATION): Calibrated {
  const q = cal.xp[windowDays];
  if (q?.upper95 === undefined) return { available: false };
  const out = ratio > q.upper95;
  return { available: true, relevant: out, level: q.upper99 !== undefined && ratio > q.upper99 ? "exceptional" : out ? "relevant" : null, lower: null, upper: q.upper95 };
}
